import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.BbQrW5_t.js";const b=JSON.parse('{"title":"中级篇·攻防实战","description":"","frontmatter":{"title":"中级篇·攻防实战","date":"2026-09-03T00:00:00.000Z"},"headers":[],"relativePath":"study/cyber-security/02-中级篇-攻防实战.md","filePath":"study/cyber-security/02-中级篇-攻防实战.md","lastUpdated":null}'),r={name:"study/cyber-security/02-中级篇-攻防实战.md"};function o(u,a,s,n,h,d){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="⚔️-中级篇-·-攻防实战-第-2-年" tabindex="-1">⚔️ 中级篇 · 攻防实战（第 2 年） <a class="header-anchor" href="#⚔️-中级篇-·-攻防实战-第-2-年" aria-label="Permalink to &quot;⚔️ 中级篇 · 攻防实战（第 2 年）&quot;">​</a></h1><blockquote><p>目标：掌握完整渗透方法论 + 审计强项变现 + 蓝队护网体验，拿下 CISP-PTE。</p></blockquote><h2 id="模块-1-渗透测试方法论-ptes-七步" tabindex="-1">模块 1：渗透测试方法论（PTES 七步） <a class="header-anchor" href="#模块-1-渗透测试方法论-ptes-七步" aria-label="Permalink to &quot;模块 1：渗透测试方法论（PTES 七步）&quot;">​</a></h2><p>侦察 → 扫描 → 枚举 → 利用 → 后渗透 → 报告。每步配一个完整靶机串讲：</p><ul><li>VulnHub 靶机串（Kioptrix 系列 → Mr-Robot → Stapler）：从&quot;扫到打&quot;的完整闭环</li><li>报告写作：漏洞描述/复现步骤/危害评级/修复建议——工程师的表达力优势区</li></ul><h2 id="模块-2-burp-进阶与-web-深水区" tabindex="-1">模块 2：Burp 进阶与 Web 深水区 <a class="header-anchor" href="#模块-2-burp-进阶与-web-深水区" aria-label="Permalink to &quot;模块 2：Burp 进阶与 Web 深水区&quot;">​</a></h2><ul><li>Intruder/Repeater/Comparer 高效组合、插件开发（你有 Java/Python 功底，写 Burp 插件不是事）</li><li>逻辑漏洞：越权/支付篡改/验证码缺陷——<strong>扫描器扫不到的才是人的价值</strong></li><li>JWT/SSRF/XXE/Web 缓存欺骗</li></ul><h2 id="模块-3-内网渗透概念链" tabindex="-1">模块 3：内网渗透概念链 <a class="header-anchor" href="#模块-3-内网渗透概念链" aria-label="Permalink to &quot;模块 3：内网渗透概念链&quot;">​</a></h2><p>信息收集 → 边界突破 → 权限维持 → 横向移动 → 域控：</p><ul><li>Kerberos 协议与委派攻击（概念+靶场复现，如 AD 靶场）</li><li>CS/MSF 框架认知（<strong>仅靶场使用</strong>）</li></ul><h2 id="模块-4-代码审计-你的王牌" tabindex="-1">模块 4：代码审计（你的王牌） <a class="header-anchor" href="#模块-4-代码审计-你的王牌" aria-label="Permalink to &quot;模块 4：代码审计（你的王牌）&quot;">​</a></h2><p>20 年代码功底直接变现：</p><ul><li>Java Web：Spring/Struts 历史漏洞模式（反序列化、SpEL/OGNL 注入）</li><li>PHP：弱类型、危险函数、上传绕过</li><li>Python：模板注入（SSTI）、pickle 反序列化、Flask 调试模式</li><li>方法：危险函数定位 → 数据流回溯 → PoC 验证（static analysis 思路迁移）</li><li>📚 资源：阿里code-audit谱系、《代码审计：企业级Web代码安全架构》</li></ul><h2 id="模块-5-蓝队与应急响应-护网入场券" tabindex="-1">模块 5：蓝队与应急响应（护网入场券） <a class="header-anchor" href="#模块-5-蓝队与应急响应-护网入场券" aria-label="Permalink to &quot;模块 5：蓝队与应急响应（护网入场券）&quot;">​</a></h2><ul><li>应急响应六步：断网取证→排查→加固→溯源（Linux/Windows 排查清单化）</li><li>SIEM 告警研判：Wazuh/奇安信天眼概念、误报判别</li><li>流量分析：webshell 识别、C2 特征概念</li></ul><h2 id="模块-6-src-实战-合法真刀" tabindex="-1">模块 6：SRC 实战（合法真刀） <a class="header-anchor" href="#模块-6-src-实战-合法真刀" aria-label="Permalink to &quot;模块 6：SRC 实战（合法真刀）&quot;">​</a></h2><ul><li>平台：补天、漏洞盒子、各厂 SRC；从教育/政府站点信息收集开始</li><li>提交规范：标题/危害等级/复现步骤/影响面——<strong>报告质量决定通过率</strong></li><li>目标：年内 3+ 有效漏洞（低危也算开张）</li></ul><h2 id="模块-7-cisp-pte-备考" tabindex="-1">模块 7：CISP-PTE 备考 <a class="header-anchor" href="#模块-7-cisp-pte-备考" aria-label="Permalink to &quot;模块 7：CISP-PTE 备考&quot;">​</a></h2><ul><li>四大场景：Web 渗透/中间件/操作系统/内网——与你的靶场积累高度重合</li><li>实操考试，工程师手感占优；2027 年内拿下</li></ul><h2 id="✅-年度验收标准" tabindex="-1">✅ 年度验收标准 <a class="header-anchor" href="#✅-年度验收标准" aria-label="Permalink to &quot;✅ 年度验收标准&quot;">​</a></h2><ul><li>[ ] VulnHub 靶机独立打穿 ≥5 台</li><li>[ ] 1 个完整代码审计报告（任一开源项目）</li><li>[ ] SRC 有效漏洞 ≥3</li><li>[ ] 护网蓝队至少 1 次正式参与</li><li>[ ] CISP-PTE 到手</li></ul>',21)])])}const p=l(r,[["render",o]]);export{b as __pageData,p as default};
